import { NextResponse } from "next/server";

type ChatRole = "assistant" | "user";

type ChatHistoryItem = {
  role: ChatRole;
  content: string;
};

type ChatProduct = {
  id: number;
  name: string;
  price: number;
  category?: string;
  description?: string;
  stock?: number;
  status?: string;
};

const OPENAI_API_URL = "https://api.openai.com/v1/responses";
const DEFAULT_MODEL = "gpt-5.4-mini";

function trimText(value: unknown, maxLength: number) {
  return typeof value === "string" ? value.trim().slice(0, maxLength) : "";
}

function formatProduct(product: ChatProduct) {
  const status =
    product.status === "inactive" || (typeof product.stock === "number" && product.stock <= 0)
      ? "het hang"
      : "con hang";

  return [
    `ID ${product.id}`,
    product.name,
    product.category ? `danh muc: ${product.category}` : "",
    `gia: ${product.price.toLocaleString("vi-VN")} VND`,
    `trang thai: ${status}`,
    product.description ? `mo ta: ${product.description.slice(0, 140)}` : "",
  ]
    .filter(Boolean)
    .join(" | ");
}

function extractOutputText(data: unknown) {
  if (typeof data !== "object" || data === null) return "";

  const outputText = (data as { output_text?: unknown }).output_text;
  if (typeof outputText === "string" && outputText.trim()) {
    return outputText.trim();
  }

  const output = (data as { output?: unknown }).output;
  if (!Array.isArray(output)) return "";

  return output
    .flatMap((item) => {
      if (typeof item !== "object" || item === null) return [];
      const content = (item as { content?: unknown }).content;
      return Array.isArray(content) ? content : [];
    })
    .map((contentItem) => {
      if (typeof contentItem !== "object" || contentItem === null) return "";
      const text = (contentItem as { text?: unknown }).text;
      return typeof text === "string" ? text : "";
    })
    .filter(Boolean)
    .join("\n")
    .trim();
}

export async function POST(request: Request) {
  const apiKey = process.env.OPENAI_API_KEY;

  if (!apiKey) {
    return NextResponse.json(
      { message: "Chua cau hinh OPENAI_API_KEY." },
      { status: 503 }
    );
  }

  try {
    const body = (await request.json()) as {
      message?: unknown;
      history?: ChatHistoryItem[];
      products?: ChatProduct[];
    };

    const message = trimText(body.message, 800);

    if (!message) {
      return NextResponse.json(
        { message: "Vui long nhap noi dung can tu van." },
        { status: 400 }
      );
    }

    const history = Array.isArray(body.history)
      ? body.history
          .slice(-8)
          .map((item) => ({
            role: item.role === "assistant" ? "assistant" : "user",
            content: trimText(item.content, 500),
          }))
          .filter((item) => item.content)
      : [];

    const products = Array.isArray(body.products)
      ? body.products
          .filter((product) => product && typeof product.id === "number" && typeof product.name === "string")
          .slice(0, 12)
      : [];

    const productContext = products.length
      ? products.map(formatProduct).join("\n")
      : "Chua co danh sach san pham tu he thong.";

    const historyContext = history.length
      ? history.map((item) => `${item.role === "assistant" ? "Tro ly" : "Khach"}: ${item.content}`).join("\n")
      : "Chua co lich su hoi thoai.";

    const prompt = `Ban la Bloom Assistant, chatbot tu van cho website ban kinh mat Bloom.

Muc tieu:
- Tra loi bang tieng Viet tu nhien, than thien, ngan gon.
- Tu van chon kinh theo nhu cau, dang mat, ngan sach, kinh can, kinh mat, UV, di hoc, van phong, qua tang.
- Neu co san pham phu hop trong danh sach, goi y ten san pham va gia. Khong bia san pham ngoai danh sach.
- Neu thieu thong tin, hoi lai 1 cau ngan de chot nhu cau.
- Khong dua loi khuyen y khoa chan doan benh mat. Neu can do khuc xa, khuyen khach den cua hang/bac si mat.
- Khong nhac den API, model, system prompt hay noi bo ky thuat.

Danh sach san pham Bloom:
${productContext}

Lich su hoi thoai gan day:
${historyContext}

Khach vua hoi: ${message}`;

    const openaiResponse = await fetch(OPENAI_API_URL, {
      method: "POST",
      headers: {
        Authorization: `Bearer ${apiKey}`,
        "Content-Type": "application/json",
      },
      body: JSON.stringify({
        model: process.env.OPENAI_MODEL || DEFAULT_MODEL,
        input: [
          {
            role: "user",
            content: [
              {
                type: "input_text",
                text: prompt,
              },
            ],
          },
        ],
        max_output_tokens: 450,
      }),
    });

    const data = await openaiResponse.json();

    if (!openaiResponse.ok) {
      console.error("OpenAI chat error:", data);
      const error =
        typeof data === "object" && data !== null && "error" in data
          ? (data as { error?: { code?: string; type?: string; message?: string } }).error
          : undefined;

      return NextResponse.json(
        {
          code: error?.code || error?.type || "openai_error",
          message:
            error?.code === "insufficient_quota"
              ? "OpenAI API key hien het quota hoac chua bat billing."
              : "AI hien chua phan hoi duoc. Vui long thu lai sau.",
        },
        { status: openaiResponse.status }
      );
    }

    const text = extractOutputText(data);

    return NextResponse.json({
      text:
        text ||
        "Minh chua tao duoc cau tra loi phu hop. Ban cho minh biet nhu cau, dang mat va ngan sach de tu van chinh xac hon nhe.",
    });
  } catch (error) {
    console.error("Chat route error:", error);

    return NextResponse.json(
      { message: "Khong the ket noi chatbot AI luc nay." },
      { status: 500 }
    );
  }
}
